using SheepGame.Core;
using UnityEditor;
using UnityEngine;

namespace SheepGame.EditorTools
{
    // Sets up the playfield object and its materials. The mesh itself is generated by
    // ApronSurface at runtime, so the apron can resize per level; this tool only has to
    // create the pieces and give the scene view something to look at.
    public static class ApronBuilder
    {
        const string MaterialDir = "Assets/_Game/Materials";
        const string ChildName = "PlayfieldApron";

        [MenuItem("SheepGame/Build Apron")]
        public static void Build()
        {
            var board = Object.FindFirstObjectByType<Board>();
            if (board == null)
            {
                EditorUtility.DisplayDialog("Build Apron", "No Board in the open scene.", "OK");
                return;
            }

            var apron = board.transform.Find(ChildName);
            if (apron == null)
            {
                var go = new GameObject(ChildName);
                Undo.RegisterCreatedObjectUndo(go, "Build apron");
                go.transform.SetParent(board.transform, false);
                apron = go.transform;
            }

            // Must clear the pack's runway slabs, whose top face sits at y = 0.2, or the
            // playfield is hidden wherever the two overlap.
            apron.localPosition = new Vector3(0f, 0.3f, 0f);
            apron.localRotation = Quaternion.identity;
            apron.localScale = Vector3.one;

            // Explicit null checks, not ??: Unity overloads == for its objects and the
            // coalescing operator bypasses that, handing back a dead component.
            if (apron.GetComponent<MeshFilter>() == null) apron.gameObject.AddComponent<MeshFilter>();
            if (apron.GetComponent<MeshRenderer>() == null) apron.gameObject.AddComponent<MeshRenderer>();

            var surface = apron.GetComponent<ApronSurface>();
            if (surface == null) surface = apron.gameObject.AddComponent<ApronSurface>();

            surface.lightCell = Material("Apron_Light", new Color(0.58f, 0.58f, 0.585f));
            surface.darkCell = Material("Apron_Dark", new Color(0.41f, 0.41f, 0.425f));
            surface.channel = Material("Apron_Taxiway", new Color(0.26f, 0.26f, 0.285f));
            surface.marking = Material("Apron_Marking", new Color(0.93f, 0.80f, 0.24f));
            surface.shore = Material("Apron_Shore", new Color(0.36f, 0.44f, 0.28f));
            surface.previewGrid = board.previewGrid;
            surface.RebuildPreview();

            Undo.RecordObject(board, "Assign apron");
            board.apron = surface;

            EditorUtility.SetDirty(board);
            EditorUtility.SetDirty(apron.gameObject);
            Debug.Log($"[APRON] preview {board.previewGrid.x}x{board.previewGrid.y} @ {board.cellSize}; " +
                      $"resizes per level at runtime");
            Selection.activeGameObject = apron.gameObject;
        }

        static Material Material(string name, Color colour)
        {
            string path = $"{MaterialDir}/{name}.mat";
            var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
                if (!AssetDatabase.IsValidFolder(MaterialDir))
                    AssetDatabase.CreateFolder("Assets/_Game", "Materials");
                AssetDatabase.CreateAsset(mat, path);
                mat.SetColor("_BaseColor", colour);
                mat.SetFloat("_Smoothness", 0.05f);
                EditorUtility.SetDirty(mat);
            }
            // Existing materials keep whatever tint they have been given by hand.
            return mat;
        }
    }
}
